{
  "tickets": [
    {
      "id": "gen-101",
      "subject": "All provider prescription favorites vanished after update",
      "body": "None of our twenty-plus doctors can see their saved medication preference lists this morning. This outage is grinding our prescribing workflow to a complete halt across the entire clinic. Fix this immediately."
    },
    {
      "id": "gen-102",
      "subject": "Question about moving misapplied insurance remittance lines",
      "body": "Hello, sorry to bother you with this, but could you please point me to the steps for fixing an insurance payment that got posted to the wrong invoice lines? We just need a quick pointer when you have a moment."
    },
    {
      "id": "gen-103",
      "subject": "Can't figure out how to stop patients from booking our procedure rooms online",
      "body": "I've spent an hour trying to restrict our online web booking so patients stop scheduling restricted visit types with the wrong doctors, but the settings just don't make sense. Why is it so difficult to limit certain appointment categories to specific providers? Please let us know how to fix this layout."
    },
    {
      "id": "gen-104",
      "subject": "URGENT: Automated reminder texts aren't going out and patients are missing slots",
      "body": "I am standing here with a waiting room full of confused patients who say they never received their automated text reminders for today. I tried checking the reminder logs in the settings menu, but everything looks blank and I have no idea what went wrong or how to trigger them manually. Please call me back right away because my schedule is completely disrupted."
    },
    {
      "id": "gen-105",
      "subject": "Process for forwarding abnormal lab reports to covering physicians",
      "body": "Good afternoon, I am writing to inquire about the proper workflow for routing specific incoming diagnostic results to covering physicians when the primary provider is out of the office. I typically click into the review queue from my dashboard, but I haven't found a clear way to annotate and reassign them without filing them into the main chart first. Could you provide some guidance or documentation on how to handle this efficiently?"
    },
    {
      "id": "gen-106",
      "subject": "Confused about setting release timers for patient portal labs",
      "body": "We are trying to figure out how to delay certain sensitive lab reports from showing up instantly in the patient portal. I went into the portal visibility settings, but I'm unsure which timer option controls the hold period before results publish. Could someone explain how these rules work?"
    },
    {
      "id": "gen-107",
      "subject": "Question regarding e-prescribing setup for a new local pharmacy",
      "body": "Hello, I am just reaching out to make sure our system has the most up-to-date routing info for a local pharmacy we frequently use. Could you confirm how we verify that our electronic prescription transmissions are going to the correct address?"
    },
    {
      "id": "gen-108",
      "subject": "Inquiry Regarding Standard Operating Procedures for Lab Sign-Off and Routing",
      "body": "Dear Support Team, I am writing to request detailed technical documentation concerning the review, annotation, and sign-off process for incoming laboratory results within our provider portal. Specifically, our medical group requires clarification on the administrative pathways for routing abnormal findings to secondary or covering staff members while maintaining audit compliance. Thank you for your assistance in clarifying these protocol settings."
    },
    {
      "id": "gen-109",
      "subject": "Inquiry regarding lab result sign-off workflow",
      "body": "Please provide documentation on how physicians review and sign incoming lab results."
    },
    {
      "id": "gen-110",
      "subject": "CRITICAL: Portal payment gateway failing for all credit card transactions",
      "body": "We are currently unable to process any patient payments through the online portal system. Front desk staff report that every credit card attempt results in an immediate processing decline error across multiple different banking institutions. Given that this affects all incoming co-pays and balances right now, we request an urgent investigation into this gateway failure."
    }
  ]
}
